cat > /tmp/build_report.py << 'PYEOF'
import json

with open('/tmp/report_data.json') as f:
    d = json.load(f)

kpis = d['kpis']
vt = d['vt_stats']
dow = d['dow_stats']
stations = d['stations_data']
days = d['days_order']

# Build sorted station table rows
station_rows = []
for sid, sv in sorted(stations.items()):
    station_rows.append({
        'id': sid,
        'location': sv['location'],
        'sessions': sv['sessions'],
        'avg_wait': sv['avg_wait'],
        'avg_load': sv['avg_load'],
        'avg_energy': sv['avg_energy'],
        'avg_reward': sv['avg_reward'],
        'avg_renewable': sv['avg_renewable'],
        'avg_queue': sv['avg_queue'],
    })
station_rows.sort(key=lambda x: x['avg_reward'])

# Worst/Best 5 stations
worst5 = station_rows[:5]
best5 = station_rows[-5:][::-1]

html = '''<!DOCTYPE html>
<html lang="en">
<head>
