  <a href="#energy">3. Energy &amp; Grid Load</a>
  <a href="#renewable">4. Renewable &amp; Pricing</a>
  <a href="#vehicles">5. Vehicle Profiles</a>
  <a href="#recommendations">6. Recommendations</a>
</nav>
'''

# ── KPI BANNER ──────────────────────────────────────────────────────────────
total_energy_mwh = round(kpis['total_energy'] / 1000, 1)
html += f'''
<div class="kpi-banner" id="kpis">
  <div class="kpi-grid">
    <div class="kpi-card">
      <div class="kpi-label">Avg Waiting Time</div>
