      <span class="kpi-badge badge-ok">35.4%</span>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Mean Opt. Reward</div>
      <div class="kpi-value">{round(kpis["mean_reward"], 1)}</div>
      <div class="kpi-unit">composite grid score</div>
      <span class="kpi-badge badge-alert">Negative</span>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Total Energy Delivered</div>
      <div class="kpi-value">{total_energy_mwh}</div>
      <div class="kpi-unit">MWh across all sessions</div>
      <span class="kpi-badge badge-info">{kpis["total_sessions"]:,} sessions</span>
    </div>
  </div>
</div>
'''

# ── SECTION 1: STATION UTILIZATION ──────────────────────────────────────────
ts_off = d['ts_counts'].get('Off-Peak', 0)
ts_peak = d['ts_counts'].get('Peak', 0)
